	db, err := openMigrationDB(databaseURL)
	if err != nil {
		return err
	}
	defer func() { _ = db.Close() }()

	for i := 0; i < n; i++ {
		if err := goose.DownContext(ctx, db, "."); err != nil {
			return fmt.Errorf("migrate down step %d: %w", i+1, err)
		}
	}
	return nil
}

